Q=[]
def add(section,title,q,answer,teach,example,correct,wrong,refs,**kw):
 n=len(Q)+1
 Q.append(dict(id=f'425-q{n:02}',number=n,section=section,title=title,q=q,answer=answer,teach=teach,example=example,correct=correct,distractors=wrong.split('|'),refs=refs,slides=[],**kw))

# All 21 professor sample prompts, in their original order, precede supporting lessons.
add(7,'Ciphertext','Cipher text is the scrambled and unreadable output of encryption.',
'TRUE. Encryption transforms plaintext into ciphertext using an algorithm and key. Decryption recovers plaintext using the appropriate key. Hashing instead produces a digest for comparison and has no decryption operation.',
'Plaintext is the readable message. Ciphertext is its encrypted representation. A digest is a different kind of output.',
'A payroll file is encrypted before transfer. Someone who intercepts the file sees ciphertext and needs the appropriate decryption key to read it.',
'True','False',[[1,'T/F 1'],[2,'p. 3'],[3,'Ch. 3, pp. 100–102']],format='tf',sample='T/F 1')
add(1,'Targets beyond payment data','Hackers these days are targeting at personal data beyond CC# and bank account# to make money.',
'TRUE. Personal information, credentials, health records, private communications, and intellectual property can support fraud, extortion, resale, and espionage. The textbook’s social-engineering example shows why account-recovery information can be valuable even without a full card number.',
'Data can have value because it helps impersonate a person or reach another account. Payment details are only one target.',
'An attacker steals a student’s login and recovery information, then uses the account to impersonate the student or access additional services.',
'True','False',[[1,'T/F 2'],[4,'08/27'],[3,'Ch. 1, pp. 3–5']],format='tf',sample='T/F 2')
add(4,'SET and stealth','SET-based attack has become more popular these days due to its stealthy penetration.',
'SET means Social-Engineer Toolkit. Your SET lab establishes that a convincing fake login page can capture credentials through user interaction, and a redirect can conceal the deception. This supports the likely classroom intention of TRUE. However, the supplied materials do not measure popularity or prove that stealth caused an increase. Treat the trend claim as instructor-dependent rather than a verified fact.',
'Learn the supported mechanism: a user trusts a deceptive page and submits credentials. Do not turn a classroom trend statement into a universal fact.',
'A fully patched employee enters a password on a cloned login page. The password is disclosed without exploiting a software flaw. Login monitoring and phishing-resistant MFA reduce the resulting risk.',
'Likely classroom intention: true; the popularity trend is unverified','False because SET cannot collect credentials|True because SET always bypasses every control|False because SET is an encryption algorithm',[[1,'T/F 3'],[5,'slides 4–8'],[6,'report']],sample='T/F 3',examEligible=False,uncertain=True)
add(5,'Reverse shell and firewall limits','The reverse shell attack is capable of defeating packet filtering firewall but not proxy firewall.',
'A reverse shell starts an outbound connection from a compromised internal host to an attacker. It can pass packet filters that allow that outbound traffic. A proxy can require authentication, restrict destinations and protocols, and inspect traffic, but its effectiveness depends on configuration and visibility. The absolute statement is technically FALSE; a proxy is not an unconditional barrier. The simplified course contrast may intend TRUE, but the exact grading expectation is unresolved.',
'Direction and policy explain the result. Outbound does not mean automatically allowed, and proxy does not mean automatically secure.',
'A workstation makes an unusual outbound connection after a malicious process starts. Correlate process and network logs, isolate the host, and restrict unnecessary egress rather than relying solely on inbound rules.',
'Technically false as an absolute; course grading needs clarification','Always true for every proxy|False because reverse shells only start inbound connections|True because a proxy encrypts every endpoint process',[[1,'T/F 4'],[2,'pp. 2–3'],[4,'09/17']],sample='T/F 4',examEligible=False,uncertain=True)
add(8,'TCP/IP is a suite','TCP/IP represent a suite of protocols including DNS, SNMP, SMPT, POP, and FTP etc.',
'TRUE with a spelling correction: SMTP, not SMPT. TCP/IP names a protocol suite spanning layers. DNS resolves names, SNMP supports device management, SMTP transfers mail, POP retrieves mail, and FTP transfers files. They are not all transport-layer protocols.',
'The suite is the whole family. TCP and IP are central members with different jobs.',
'A mail application resolves a server name with DNS, connects using transport protocols, and uses SMTP to send mail. Several suite members cooperate.',
'True','False',[[1,'T/F 5, labeled Lecture 6'],[2,'p. 3, Lecture 8']],format='tf',sample='T/F 5')
add(1,'Security job roles','Ian analyzes and designs security solutions and identifies users’ needs. Which position is this?',
'A. Security administrator. Ciampa Chapter 1, printed page 6 (PDF page 34), assigns these duties to the security administrator. A technician configures and troubleshoots tools; a manager supervises personnel; the CISO directs security at the executive level. This resolves the second guide’s textbook-needed placeholder.',
'Match the duties to this textbook’s definition. Job titles at actual companies can vary.',
'An employee evaluates staff security needs and designs a suitable access-control solution while managing daily security technology. That matches the administrator role in the book.',
'Security administrator','Security technician|Security officer|Security manager',[[1,'MC 1'],[2,'p. 3, unresolved entry'],[3,'Ch. 1, p. 6; PDF p. 34']],sample='MC 1')
add(3,'Race condition','What is a race condition?',
'D. Concurrent execution accesses shared state without adequate synchronization, so the result depends on timing or ordering and can become unintended. A race condition is a concurrency flaw, not a synonym for DDoS, slow processing, or a race to patch before attackers act.',
'Two operations interfere because each assumes it can use the same state safely. Locking, atomic operations, or safe transaction design can prevent this.',
'Two checkout requests both see one remaining item before either updates stock. Both complete, selling the same item twice.',
'Concurrent execution accesses a shared resource and causes unintended consequences','A race to patch a newly discovered vulnerability|A software update released before discovery|An attack finishing before antivirus scanning',[[1,'MC 2'],[3,'Ch. 1, p. 14'],[4,'09/08, corrected']],sample='MC 2')
add(4,'Vishing','Which statement is correct about vishing?',
'C. VoIP makes caller-ID spoofing easier. Vishing is voice phishing: an attacker uses a call or voice message to trick someone into revealing information or performing an action. Calls can be automated, targeted, or broadly distributed; it does not always require a live person.',
'Voice is the identifying feature. Caller ID is a claim, not proof of identity.',
'A caller claims to be the help desk and asks for a login code. Hang up and verify through an independently known help-desk number.',
'VoIP makes caller-ID spoofing easier','It is only tailored to organizations|It only targets large organizations|It always uses a real person to call',[[1,'MC 3'],[2,'p. 2']],sample='MC 3')
add(4,'Email sender investigation','To investigate a phishing email, where would you go for sender information?',
'D. Email header. Full headers provide routing and sender-related fields such as Received, Return-Path, and authentication results. Compare these with the claimed sender and timestamps. A display name, body, attachment, or embedded URL alone does not establish who sent the message. Some header fields can also be forged; establish trusted receiving-system boundaries.',
'Headers provide evidence for investigation. Reading the visible sender label alone is not enough.',
'An email claims to come from campus IT but uses a lookalike domain and urgent password language. Preserve the message and inspect headers through the approved reporting process.',
'Email header','Attachment|Embedded URL|Email body',[[1,'MC 4'],[2,'p. 2'],[7,'p. 3, phishing example']],sample='MC 4',originalOptions=['Attachment','Embedded URL','Anti-virus','Email Header','Email Body'])
add(6,'Static analysis terminology','Which of the following is a static analysis tool: Firebug, McAfee Advisor, JSUnpack, Norton SafeWeb, or OpenSSL?',
'JSUnpack is the likely intended classroom selection because it decodes and analyzes suspicious JavaScript. Keep the second guide’s qualification: JSUnpack can execute or emulate JavaScript as part of analysis, so calling it purely static is imprecise. Firebug is a browser debugger, SiteAdvisor and Safe Web are reputation services, and OpenSSL is a cryptographic toolkit. Static analysis examines code without executing it; dynamic analysis observes execution.',
'The exam’s tool label and the general definition are separate things to remember. Automated does not automatically mean static.',
'Reading script text and decoding an embedded string without running the script is static work. Observing redirects while script executes in an isolated environment is dynamic work.',
'JSUnpack is likely intended; its analysis is not purely static','McAfee Advisor is a source-code compiler|Norton SafeWeb is an offline disassembler|OpenSSL is a browser reputation database',[[1,'MC 5'],[2,'pp. 2, 4']],sample='MC 5',examEligible=False,uncertain=True,originalOptions=['Firebug','McAfee Advisor','JSUnpack','Norton SafeWeb','OpenSSL'])
add(8,'TCP reliability','Which protocol is responsible for data packet quality and basic security features in transmission?',
'A. TCP is the likely intended answer: Transmission Control Protocol provides reliable, ordered byte-stream delivery using acknowledgments, retransmissions, sequencing, and a checksum. IP supplies addressing and routing. TCP’s reliability and checksum are not confidentiality or cryptographic authentication. HTTPS adds TLS security at a different level. The phrase basic security in the prompt is loose.',
'TCP handles reliable delivery. It does not itself encrypt your message or prove the other party’s identity.',
'A file download needs all bytes in order. TCP can retransmit missing data; TLS is needed separately to protect confidentiality and authenticate the server.',
'TCP','IP|UDP|HTTP',[[1,'MC 6'],[2,'p. 3'],[4,'10/15, corrected']],sample='MC 6',originalOptions=['TCP','IP','UDP','HTTPS','HTTP'])
add(2,'False positive','An IDS raises an alarm on normal, nonmalicious traffic. What error is this?',
'False positive, also called a Type I error in your notes. A false negative (Type II) occurs when malicious traffic is treated as benign. False positives consume analyst time and can interrupt legitimate work if prevention blocks the traffic; false negatives leave attacks undetected.',
'Positive means the system says threat. False means that conclusion is wrong.',
'A legitimate backup triggers a malware alert: false positive. A real malicious download produces no alert: false negative.',
'False positive','False negative|True positive|True negative',[[1,'Fill 1'],[4,'09/01, 09/06']],sample='Fill 1',format='fill')
add(2,'Dormant program and C2','A program or part of a program lies dormant until triggered by the C2 server. What is it?',
'The wording combines definitions and does not establish a unique answer. A logic bomb is dormant code activated by a specified condition (Ciampa Chapter 2, printed p. 65); a bot or implant can receive commands from a command-and-control (C2) server; a backdoor provides concealed access. If the emphasis is dormant code with a trigger, logic bomb is plausible. If the emphasis is remote C2 instructions, bot is plausible. Keep this item for clarification rather than memorize a guessed single-word key.',
'Dormant trigger and remote control are overlapping properties, not one unique malware name.',
'A timed destructive routine is a logic bomb. An infected workstation waiting for remote instructions is a bot. Both can be dormant, but they are classified by different behavior.',
'Ambiguous: logic bomb for a condition trigger; bot for C2 control','Definitely checksum|Definitely ciphertext|Definitely a firewall',[[1,'Fill 2'],[2,'p. 4'],[3,'Ch. 2, p. 65; PDF p. 93']],sample='Fill 2',examEligible=False,uncertain=True)
add(7,'Hard fork','What splits one blockchain instance into two through an incompatible protocol change?',
'Hard fork is the guide’s intended term. It changes consensus rules incompatibly, so nodes following different rules can maintain different chains. A persistent split depends on participants continuing both histories; a hard fork need not always leave two lasting communities. A soft fork tightens accepted rules compatibly for older nodes.',
'A protocol disagreement is different from two miners briefly finding competing blocks.',
'One group adopts a rule that older nodes reject while another group continues the old rules. Their accepted transaction histories can diverge.',
'Hard fork','Checksum|Digital signature|Symmetric key',[[1,'Fill 3'],[2,'p. 3']],sample='Fill 3',format='fill')
add(8,'Checksum','What tool checks integrity of packet content?',
'Checksum. The receiver recomputes an error-detection value and compares it with the transmitted value to detect accidental corruption. An ordinary Internet checksum is not SHA-256 and does not defend against an attacker who can alter data and recompute the checksum. Cryptographic integrity requires a suitable authenticated mechanism such as a MAC or signature.',
'An error check catches transmission damage. Authenticating malicious changes requires a stronger, trusted construction.',
'A bit flips while a segment is transmitted and the checksum comparison fails. The receiver can discard it; reliable transport may retransmit.',
'Checksum','Ciphertext|Public key|Nonce',[[1,'Fill 4'],[2,'p. 3'],[4,'10/15, corrected']],sample='Fill 4',format='fill')
add(5,'Why patching becomes easier','How do bandwidth, cloud computing, big data/analytics, and virtualization alleviate security-update pressure?',
'More bandwidth speeds patch distribution, although deployments still need scheduling. Cloud-based and centralized management can coordinate updates across fleets, while customers retain responsibilities for their own systems and configurations. Analytics helps inventory systems, prioritize exposure, and detect failed updates. Virtualization supports representative test environments, snapshots, and rollback. Together these reduce transfer, coordination, decision, and testing costs. They do not remove compatibility testing, outages, or zero-day risk.',
'Organize your discussion by the bottleneck each technology reduces. State one benefit and one limitation for each.',
'A business inventories vulnerable devices, prioritizes exposed servers, tests a patch on representative VMs, pilots deployment, monitors failures, and rolls out in stages with rollback available.',
'Distribution, coordination, prioritization, and safe testing become easier','All updates can be installed without testing|Snapshots eliminate the need for backups|Cloud providers automatically patch every customer application',[[1,'Discussion 1'],[2,'p. 4'],[4,'09/15'],[9,'VM setup']],sample='Discussion 1',format='discussion',rubric=['Explain bandwidth and distribution','Explain cloud and shared responsibility','Explain analytics and prioritization','Explain VM testing and rollback','Keep testing and availability tradeoffs'])
add(3,'Viruses and other malware','What are the major types of computer viruses, and how do virus, worm, scareware, adware, spyware, and backdoor differ?',
'A virus attaches to a host file or document and replicates when the host runs; a worm is a standalone program that can propagate across networks. Scareware uses fraudulent alarms to pressure payment or installation. Adware displays unwanted advertising; spyware secretly collects information; a backdoor bypasses normal access controls. In this textbook’s Chapter 2, viruses include program/file viruses and macro viruses, with appender infection and armored concealment techniques: Swiss cheese, split infection, oligomorphic, polymorphic, and metamorphic mutation. Boot-sector viruses are another common category, but the supplied edition emphasizes the preceding list. The guide labels this Ch. 1; the relevant detail is actually Ch. 2, pp. 55–65.',
'Compare how malware spreads, hides, and acts. These categories can overlap: a backdoor may install spyware that includes a keylogger.',
'An infected document executes a malicious macro; a network worm spreads independently; a fake antivirus page scares a user into paying. Each has a different mechanism and defense.',
'Virus needs a host; worm propagates independently; other names describe behavior','All malware is a virus|Scareware is legitimate antivirus|Backdoors are the same as checksums',[[1,'Discussion 2'],[2,'p. 4'],[3,'Ch. 2, pp. 55–65'],[7,'p. 2'],[8,'slides 3–5']],sample='Discussion 2',format='discussion',rubric=['Define all six categories','Compare virus and worm propagation','Include program and macro viruses','Explain armored and mutation examples','Connect threats to layered defenses'])
add(7,'Confidentiality authentication obfuscation','How do confidentiality, authentication, and obfuscation correlate in cryptographic applications?',
'Confidentiality limits who can read data, usually through encryption. Authentication establishes a claimed identity or data origin through a suitable cryptographic protocol; a digital signature can bind a message to a signing key. Obfuscation makes information or implementation details harder to understand, and the textbook includes it among cryptographic protections. These goals complement one another but do not substitute for one another. Encryption to a recipient’s public key does not by itself identify the sender; an ordinary hash does not authenticate an origin; signing does not encrypt the message. For secrecy plus sender authentication, use a properly designed encrypted and authenticated scheme.',
'Ask three separate questions: who can read, who created or approved it, and what details are being obscured?',
'A sender signs a document with the sender’s private signing key and protects the content for the recipient. The recipient decrypts and verifies using the appropriate keys and a trusted identity binding.',
'Encryption protects reading; authentication proves origin; obfuscation obscures details','A hash alone proves the sender|A signature automatically hides the message|Obfuscation always replaces encryption',[[1,'Discussion 3'],[2,'pp. 2, 4'],[3,'Ch. 3, pp. 105–106, 120–122'],[4,'09/29, 10/15']],sample='Discussion 3',format='discussion',rubric=['Define each goal','Explain encryption and recipient keys','Explain signature and sender keys','Separate hash from authentication','Explain why obfuscation alone is insufficient'])
add(7,'Collision resistance','Hash algorithms are naturally resistant to hash collisions. Why?',
'Qualify the premise: a well-designed cryptographic hash aims for computational collision resistance. A fixed n-bit digest has 2^n possible outputs, so different inputs must sometimes collide. Good output distribution and no practical structural shortcuts make finding a collision expensive. The generic birthday bound is roughly 2^(n/2) work to find any pair; finding an input for a particular digest is a different preimage problem. SHA-256 produces 256 bits (64 hexadecimal characters), with an ideal generic collision bound around 2^128. MD5 and SHA-1 demonstrate that not every hash is collision resistant. Collision resistant never means collision impossible.',
'A large output space makes a matching pair hard to find, but fixed-length outputs cannot uniquely represent every possible input.',
'Two distinct files could share a digest. A trusted expected hash can help verify a download, but an attacker changing both file and untrusted posted hash defeats that simple comparison.',
'Large well-distributed outputs make finding collisions computationally difficult','Collisions are mathematically impossible|Hashing encrypts every input uniquely|All hash algorithms have equal collision resistance',[[1,'Discussion 4'],[2,'pp. 3–4'],[3,'Ch. 3, pp. 125–126'],[4,'09/29, corrected']],sample='Discussion 4',format='discussion',rubric=['Admit collisions exist','Explain fixed output space','Explain computational difficulty','Distinguish birthday bound and preimage','Use SHA-256 and weak-hash contrast'])
add(7,'Blockchain mechanics and tradeoffs','How does blockchain work? What are its pros and cons?',
'Transactions are grouped into blocks. A block header commits to transaction data through a Merkle root and includes the previous block’s hash. Altering data changes its hash and breaks later commitments. Nodes validate transactions and consensus determines the accepted history. In Bitcoin, proof of work requires miners to search nonces for a header hash meeting a target; the accepted valid chain has the greatest cumulative work. More confirmations make rewriting history harder under the network’s security assumptions. Benefits include shared auditability and tamper evidence. Costs include proof-of-work energy use, throughput/latency limits, public-data privacy issues, key loss, and difficult correction of erroneous entries. Blockchain is not an absolute guarantee of truth or immutability, and not all blockchains use proof of work.',
'Hashes connect history; signatures authorize spending; consensus resolves competing histories. None does all three jobs alone.',
'Change an old record in a teaching chain. Its hash and descendants no longer match. Rehashing a local copy is easy in a toy demo; convincing a real consensus network is the costly part.',
'Hash links plus validation and consensus create a shared tamper-evident history','Encryption alone makes every transaction private|A nonce is the owner’s password|Every blockchain must use Bitcoin mining',[[1,'Discussion 5'],[2,'pp. 3–4'],[11,'Blockchain exercise']],sample='Discussion 5',format='discussion',rubric=['Explain block contents and previous hash','Explain Merkle root','Explain nonce proof of work and consensus','Explain tamper evidence and confirmations','Give benefits and limitations'])
add(7,'Bitcoin and ownership transfer','What is a bitcoin?',
'Bitcoin is a peer-to-peer digital currency whose transaction history is recorded on a blockchain. A spender authorizes use of earlier unspent transaction outputs by satisfying their spending conditions, typically with a digital signature created using the spender’s private key. A new output specifies conditions for the receiver. Nodes verify authorization and check for double spending; mining orders valid transactions through proof of work. SHA-256 contributes to hashing and proof of work, not encryption of a coin. An address is commonly derived from a key or script and is not always the raw public key. Public ledger transparency provides pseudonymity, not guaranteed anonymity. Miners receive a block subsidy and transaction fees as incentives.',
'Ownership means the ability to authorize spending under the output’s rules. You transfer spending rights through a transaction; you do not email a secret coin file.',
'Alice signs a transaction spending an output she controls and creating one for Bob. Others verify it with public information. Bob later spends by satisfying his output’s conditions.',
'A peer-to-peer currency with signature-authorized spending and blockchain consensus','A coin encrypted with SHA-256 and emailed|A central-bank database with no signatures|An anonymous password shared by all miners',[[1,'Discussion 6'],[2,'pp. 3–4'],[4,'10/15'],[11,'Nakamoto’s Coin']],sample='Discussion 6',format='discussion',rubric=['Define peer-to-peer currency and ledger','Explain sender private key and verification','Explain recipient output and ownership','Separate signatures hashes and proof of work','Explain pseudonymity incentives and double spending'])

# Supporting scope: lectures 1–8, textbook chapters 1 and 3, and lab interpretation.
rows=[
(1,'CIA and risk','What do confidentiality, integrity, and availability protect?','Confidentiality restricts disclosure, integrity protects against unauthorized alteration, and availability provides access when needed. An asset has value; a vulnerability is a weakness; a threat can cause harm; risk concerns likelihood and impact. Risk responses include accept, avoid, mitigate, and transfer. Controls can be technical, administrative, or physical.','A leaked record harms confidentiality; a changed grade harms integrity; an unavailable portal harms availability.','A hospital considers ransomware risk to patient records. Backups improve recovery, access controls restrict disclosure, and monitoring detects changes.','Disclosure, alteration, and loss of access','CPU, Internet, and antivirus|Only encryption strength|The same property under three names',[[3,'Ch. 1, pp. 18–24']]),
(1,'Threat actors and priorities','How do motivations and access distinguish threat actors?','Organized crime often seeks profit; hacktivists pursue ideological goals; nation-state actors may seek espionage or disruption; insiders already have trusted access; script kiddies rely on existing tools; vulnerability brokers sell knowledge. Advanced persistent threats involve sustained, targeted activity. Zero-day describes an unknown or unpatched vulnerability context, not a person. Your notes emphasize social engineering and insiders as pressing concerns; actual priority depends on organizational exposure.','Identify who, why, capability, and access rather than assuming one threat always ranks first.','A disgruntled staff member has access to payroll. An outside criminal uses a phishing toolkit. The controls must account for both trusted and untrusted access.','Motivation, capability, resources, and access help assess threats','Zero-day is a job title|Insiders cannot be malicious|Every attacker needs advanced programming skills',[[3,'Ch. 1, pp. 25–31'],[4,'08/27'],[10,'career exercise used for role context']]),
(1,'Five defense principles','How do layering, limiting, diversity, obscurity, and simplicity improve security?','Layering adds multiple safeguards. Limiting gives only necessary access. Diversity reduces shared failure modes across products or controls. Obscurity hides unnecessary details but cannot be the sole defense. Simplicity makes controls easier to understand and manage. Frameworks and reference architectures organize a security program; some are regulatory, industry-specific, national, or international.','Several well-managed controls help more than one opaque, overcomplicated control.','Email filtering, a standard-user account, endpoint monitoring, and recovery procedures protect different points in a phishing incident.','Layer controls, limit rights, diversify, obscure details, and keep management simple','Publish all secrets to simplify access|Use only one secret product|Give all users administrator rights',[[3,'Ch. 1, pp. 32–35']]),
(2,'Defense in depth and architecture','How do choke points, visibility, availability, and scalability guide network defense?','Use safeguards at both perimeter and endpoint. A choke point is a controlled entry or exit where traffic can be inspected; internal segmentation also matters. Visibility requires useful telemetry at these boundaries and on hosts. Redundancy reduces single points of failure, while scalability supports changing workload. Balance security with business availability, budget, and capacity.','A strong front door cannot show what is happening inside every room. Host and internal telemetry fill that gap.','A retailer inspects gateway traffic, segments payment systems, collects endpoint events, and uses redundant devices to avoid a single outage.','Layered inspection and telemetry with capacity and availability planning','A perimeter firewall eliminates all endpoint risk|Visibility means capturing only public web pages|Redundancy makes filtering rules unnecessary',[[2,'p. 1'],[4,'09/01, 09/06']]),
(2,'IDS versus IPS','What is the functional difference between IDS and IPS?','An IDS detects suspicious activity and alerts. An IPS can actively block or disrupt traffic or activity. Either can use signatures, heuristics, behavior, or other techniques; an IPS does not require AI. Host IPS observes local activity; network controls observe traffic. Tune false positives and false negatives in light of business impact.','Detection versus prevention describes the response, not whether the tool possesses its own intelligence.','An alert-only sensor reports suspicious traffic. An inline prevention rule blocks the same traffic, potentially interrupting legitimate service if the rule is wrong.','IDS alerts; IPS can actively intervene','IDS always blocks packets|IPS always requires AI|An antivirus database makes false negatives impossible',[[2,'p. 1'],[4,'09/06, corrected']]),
(2,'PCAP flow proxy and allowlisting','How do full packet capture, flow data, proxies, and application allowlisting differ?','Full PCAP records packet bytes within capture limits, useful for detailed reconstruction; encrypted payloads remain encrypted without suitable keys. Flow records summarize conversations such as endpoints, times, ports, and byte counts. A proxy mediates application requests and can enforce policy and log activity. Application allowlisting permits approved software and restricts other execution. These controls complement rather than replace one another.','Choose the evidence or control for the question: content, conversation metadata, mediated requests, or permitted programs.','An analyst finds a long outbound connection in flow logs, examines available packet evidence, then correlates it with proxy and endpoint events.','PCAP captures bytes; flow summarizes; proxy mediates; allowlisting restricts execution','Flow records always include every file|A proxy is the same as PCAP|Allowlisting permits all unknown programs',[[2,'p. 1'],[4,'09/01, 09/06']]),
(3,'DDoS SYN flood and Slowloris','How do SYN flooding and Slowloris affect availability?','Denial of service exhausts resources or disrupts access; distributed DoS uses multiple sources. A SYN flood abuses half-open TCP connection state. Slowloris holds many HTTP connections with incomplete, slow requests and may work from few sources. Mitigations include upstream filtering, rate and connection limits, appropriate timeouts, SYN protections, and capacity planning. DDoS can distract responders but is not always a distraction or a race condition.','Bandwidth floods and application connection exhaustion stress different resources. Match mitigation to the bottleneck.','A service is unavailable despite modest bandwidth because many connections remain incomplete. Appropriate connection limits and timeouts address this pattern.','They consume connection resources and deny legitimate access','All DoS attacks require a giant botnet|Slowloris encrypts a database|A SYN flood is simply a race condition',[[2,'p. 1'],[4,'09/08, 10/15']]),
(3,'SQL injection versus XSS','What changes when malicious input reaches a SQL query versus a browser?','SQL injection makes untrusted input influence database query structure. Parameterized queries keep data separate from SQL commands; least-privilege database accounts limit harm. XSS causes attacker-controlled script to execute in a user’s browser in a trusted site’s context. Use context-aware output encoding, safe APIs, and appropriate sanitization for allowed HTML. Input validation supports both but is insufficient alone. WebGoat is a deliberately vulnerable teaching application. Neither attack is limited to one operating system.','Ask where the injected content is interpreted: database query engine or victim browser. XSS is not automatically full server control.','A search value must remain a SQL parameter. A comment displayed on a page must remain text or sanitized allowed HTML rather than executable script.','SQLi changes query interpretation; XSS executes script in the browser','Both are prevented by antivirus alone|XSS always takes full control of the application server|Prepared statements alone prevent every XSS flaw',[[2,'p. 1'],[4,'09/08–09/10, corrected'],[11,'XSS & SQLi exercise']]),
(4,'Social-engineering families','How do phishing, spear phishing, smishing, vishing, and a 419 scam differ?','Phishing uses deceptive communication to elicit information or action. Spear phishing targets particular recipients using tailored context. Smishing uses SMS; vishing uses voice. A 419 or advance-fee scam promises a benefit to obtain money or sensitive data upfront. Scareware creates false security urgency. Verify requests through independent trusted channels and report suspicious messages.','Channel, targeting, and pretext distinguish these related attacks.','An urgent campus-password message aimed at named students is targeted phishing. A phone request for login codes is vishing.','Targeting and communication channel distinguish the methods','Smishing uses only voice calls|Spear phishing is always random|419 scams provide guaranteed legitimate rewards',[[2,'pp. 1–2'],[7,'p. 3']]),
(4,'Metasploit and SET business case','What do the Metasploit and SET labs demonstrate for a business?','Metasploit organizes authorized security testing through exploit, payload, auxiliary, and post-exploitation capabilities. SET is a separate TrustedSec social-engineering toolkit that can integrate with Metasploit; it is not simply a Metasploit module. The credential-harvesting lab demonstrates how user trust can disclose credentials without a software exploit. Prevent with training, filtering, phishing-resistant MFA, and login monitoring. If credentials are disclosed, report, reset affected secrets from a trusted device, revoke sessions, and investigate related access.','Explain the weakness, business consequence, evidence, and defense. Exact tool-menu commands are not the stated exam priority.','A fake staff login collects a test password in the isolated lab. A business analogue is account takeover leading to exposed records or fraudulent actions.','Structured testing and social-engineering simulation reveal technical and human weaknesses','SET is a hash algorithm|Patching alone prevents every fake-login attack|A captured password always means code executed on the host',[[4,'10/15'],[5,'slides 3–8 and notes'],[6,'report'],[11,'Lab 2 assignment']]),
(4,'Keylogger and encryption boundaries','Why can a keylogger steal information even when a website uses HTTPS?','A keylogger records input on the endpoint, often before TLS encrypts it for transport. Software variants may intercept input APIs, run with elevated privileges, or observe forms; hardware variants can sit between keyboard and computer. Not every keylogger requires process injection or admin rights. Defend with endpoint monitoring, least privilege, updates, application controls, physical inspection where appropriate, and phishing-resistant authentication. Transport encryption alone cannot secure a compromised endpoint.','Protection during transmission does not protect the moment data is typed on a compromised device.','The lab’s isolated victim records test keystrokes. An organization should investigate the endpoint and account access rather than assume HTTPS prevented disclosure.','The endpoint can capture keystrokes before transport encryption','HTTPS disables all keyboard monitoring|All keyloggers are network routers|Only encrypted keystrokes can be logged',[[7,'pp. 1–2'],[8,'slides 3–8 and notes']]),
(5,'Hardening and patch workflow','What belongs in OS hardening and a safe patch rollout?','Inventory assets, apply tested updates, use standard-user accounts, remove unnecessary services, enable appropriate endpoint firewall and protection, restrict software execution, and monitor changes. A patch workflow downloads, tests, pilots, schedules, deploys, and verifies, with rollback planning. NAC checks access posture; GPO distributes domain policy. Patching addresses known vulnerabilities but does not eliminate zero-days. Legacy tool names in notes are historical examples, not a current shopping list.','Reduce attack surface and limit damage before an incident. Verify that deployed controls actually work.','A business tests a browser update in a representative VM, deploys to a pilot group, monitors compatibility, then expands rollout.','Test updates, reduce services and privileges, enforce controls, and verify','Disable all production firewalls to match a lab|Allow daily work with administrator rights|Assume automatic updates can never fail',[[2,'p. 2'],[4,'09/15–09/17']]),
(5,'Visibility and incident interpretation','How should an analyst interpret an attack timeline?','Correlate host process events, network connections, authentication logs, and file changes. A SOC coordinates monitoring and response. EDR supplies endpoint detection and response evidence. Reconnaissance gathers information; privilege escalation increases rights; credential dumping extracts stored authentication material; SMB commonly supports network file sharing. Process hollowing replaces or maps malicious code into another process context. PowerShell is an administration shell and scripting environment; a sandbox is an isolated execution environment. DLL means Dynamic Link Library. Infiltration gains entry; exfiltration removes information.','Separate the tools, techniques, evidence, and outcomes. Seeing a tool name alone does not establish malicious intent.','An Office process starts unusual PowerShell, followed by a new outbound connection and credential access. Build a timeline, identify affected hosts, preserve evidence, and contain according to the incident plan.','Correlate process, network, identity, and file evidence into a timeline','Treat all PowerShell use as proof of compromise|Sandbox means the same as PowerShell|Exfiltration means installing a software update',[[11,'09/17 visibility exercise'],[4,'09/17']]),
(5,'Lab 0 and isolation','What do the VirtualBox network adapters and snapshots contribute to safe testing?','The host runs VirtualBox and the guest operating systems. The lab uses Kali and Windows 7 guests with an internal network for guest-to-guest tests and NAT for controlled Internet access during setup. Internal networking does not make the entire host immune; additional adapters and sharing features affect exposure. Static guest addresses support predictable connectivity. Snapshots help restore a known lab state but do not replace independent backups. Disabling a guest firewall was an intentionally weakened lab condition, not a production hardening practice.','Explain why a control is disabled in a demonstration and why a real organization would enforce it.','A tester uses an isolated guest network to observe activity, takes a baseline snapshot, and restores the guest after the exercise.','Isolation and reproducible guest states support controlled testing','NAT and internal network are identical|A snapshot replaces every backup|Disabling production firewalls is a hardening step',[[9,'Parts I–V'],[4,'08/27'],[8,'slide 7']]),
(6,'Suspicious website analysis','How do static, dynamic, and reputation checks complement each other?','Static work inspects HTML, scripts, redirects, and embedded references without execution. Dynamic work observes behavior in an isolated environment, including processes, files, registry, and traffic. Reputation checks compare against previous reports. Automation is fast but can miss new threats; manual investigation provides context but takes skill and time. A legitimate site can be compromised. Firebug, Malzilla, Wepawet, JSUnpack, SiteAdvisor, and Safe Web are course-era examples.','A known domain and a clean reputation report are evidence, not guarantees.','A site’s source includes a hidden redirect. An analyst reviews it, consults reputation evidence, and examines behavior in an approved sandbox.','Combine source inspection, isolated behavior observation, and reputation evidence','A familiar brand proves a page is safe|Automated always means static|A clean reputation scan proves no new malware exists',[[2,'p. 2']]),
(7,'Hash encryption and signatures','Which cryptographic operation should you use for secrecy, comparison, or signed origin?','Encryption protects content confidentiality and is reversible with the correct key. Hashing produces a deterministic fixed-length digest with no intended inverse. A signature uses a private signing key and is checked with a corresponding public key to authenticate authorized data and detect alteration. A bare hash has no secret and does not prove origin. HMAC combines a secret key and hash for integrity and shared-key authentication; it is not encryption and does not provide the same public verification as a signature.','Choose the operation by the required property rather than calling every cryptographic output ciphertext.','A document can be hashed for comparison, signed to show approval, and encrypted for its intended reader. These operations have separate roles.','Encrypt for secrecy, hash for comparison, sign for verifiable authorization','Decrypt SHA-256 to recover the message|Use a bare hash to prove sender identity|Signing automatically encrypts the whole document',[[3,'Ch. 3, pp. 109–113, 120–122'],[4,'09/29, 10/15']]),
(7,'Symmetric and asymmetric keys','Whose key does a sender use for confidentiality, and whose for a signature?','Symmetric encryption shares one secret for encryption and decryption and is efficient for bulk data. Public-key encryption uses the recipient’s public key and recipient’s private key to decrypt. Signing uses the sender’s private key and verification uses the sender’s public key. Verify the binding between a public key and a claimed identity. AES is symmetric; RSA and ECC belong to asymmetric families. DES and 3DES are historical course examples, not preferred new-system choices.','For secrecy think recipient; for signature think sender. Protect private and shared secret keys.','Alice wants only Bob to read a message and wants Bob to verify her approval. She protects it for Bob and signs it using her own signing key.','Recipient keys protect reading; sender keys provide signature verification','Encrypt with sender public key for only Bob to read|Share all private keys for authentication|Use receiver private key on the sender’s machine',[[3,'Ch. 3, pp. 114–123'],[4,'09/29, 10/15']]),
(7,'RSA arithmetic','How does the classroom RSA example connect public and private exponents?','For distinct primes p and q, n=pq and φ(n)=(p−1)(q−1). Choose e with gcd(e,φ(n))=1 and choose d so ed ≡ 1 mod φ(n). Textbook notation may use m for φ(n). Classroom encryption is c=m^e mod n and decryption is m=c^d mod n. With p=5, q=11, n=55, φ=40, e=3, d=27: message 7 gives ciphertext 13 and decrypts to 7. The notes’ condition using e and n is incorrect; coprimality with φ(n) is essential. Small unpadded examples teach arithmetic and are not secure deployments.','The private exponent reverses the public exponent modulo n for correctly constructed RSA. Real implementations require safe key sizes and padding.','3×27=81 leaves remainder 1 modulo 40. Then 7³ mod 55=13 and 13²⁷ mod 55=7.','Choose e coprime to φ(n), then d as its modular inverse','Choose e equal to φ(n)|Use addition instead of modular exponentiation|Make d public and hide e',[[4,'09/29 RSA illustration, corrected'],[3,'Ch. 3, pp. 118–119']]),
(7,'Nonce Merkle root and tampering','What do a nonce, Merkle root, and previous-block hash do?','A proof-of-work nonce is a value miners vary while searching for a block-header hash meeting a target. A Merkle root commits to the block’s transactions using a tree of hashes. The previous-block hash links a block to its predecessor. Altering a transaction changes its commitment and invalidates later links unless recomputed. A toy rehash demonstration is not the full security model: distributed validation and cumulative proof of work make rewriting accepted history difficult.','Separate the miner’s search value, the transaction commitment, and the history link.','Changing one transaction changes the Merkle root, then its block header hash and the descendants’ required links.','Nonce supports work search; Merkle root commits transactions; prior hash links history','Nonce is the receiver’s private key|Merkle root stores every private password|Prior hash encrypts all previous transactions',[[11,'Blockchain questions 1–6'],[2,'p. 3']]),
(7,'Bitcoin incentives privacy and double spending','Why use signatures, incentives, and consensus together in Bitcoin?','Signatures demonstrate authorization to spend. Nodes check spending rules, including whether an output is unspent. Consensus orders transactions so competing spends do not both become accepted history. A block subsidy and fees incentivize miners. Public records use addresses or spending scripts rather than mandatory civil identities, but linked transactions can reveal relationships. This is pseudonymity. Nakamoto’s paper contrasts verification by cryptographic proof with the reversal costs, mediation, and trust demands of financial intermediaries.','Authorization does not establish which of two conflicting authorized spends came first; network agreement addresses that ordering problem.','An owner attempts to spend the same output twice. Both signatures could be valid, but both transactions cannot be accepted in one valid history.','Signatures authorize, consensus orders, and rewards motivate participation','Hashing alone prevents all double spending|All Bitcoin addresses guarantee anonymity|Miners can authorize spending anyone’s coins',[[11,'Nakamoto’s Coin questions 1–4'],[4,'10/15']]),
(8,'TCP UDP IP and handshake','How do TCP, UDP, and IP differ, and what is the TCP handshake?', 'TCP provides a reliable ordered byte stream, using SYN, SYN-ACK, ACK for conventional connection establishment. UDP provides datagrams without TCP-style delivery or ordering guarantees and is useful where applications tolerate loss or implement their own recovery. Both operate at the transport layer. IP addresses and routes packets at the network layer with best-effort delivery. UDP is not restricted to private networks, and TCP does not guarantee timeliness or encryption. Packet lengths can vary.','Reliability, latency tradeoffs, and routing are separate design concerns.','A voice application may prioritize timely delivery over retransmitting old audio; a file transfer needs all bytes. Both rely on IP routing.','TCP reliable stream; UDP datagrams; IP best-effort routing','IP guarantees every byte in order|UDP is only allowed on private networks|TCP stands for Transportation Control Protocol',[[2,'p. 3'],[4,'10/15, corrected']]),
(8,'Network administration protocols','What do DNS, DNSSEC, SNMP, ICMP, FTP, SMTP, and POP contribute?','DNS resolves names and other records; poisoning supplies false resolution information. DNSSEC authenticates signed DNS data and integrity when correctly validated, without encrypting ordinary DNS queries. SNMP monitors and manages devices; v3 supports stronger protection. ICMP carries network control and diagnostic messages, including ping. Traditional FTP transfers files without encryption: port 21 controls, port 20 is traditionally active-mode data, while passive mode negotiates data ports. SMTP transfers mail and POP retrieves it. Wireshark analyzes packets; log correlation helps investigation.','Match each service to its job before memorizing associated names and port facts.','A name resolves unexpectedly, so an analyst checks DNS evidence and validation. Separate authentication logs and packet metadata help establish the incident timeline.','Different protocols handle naming, management, diagnostics, files, and email','DNSSEC encrypts every website|FTP always uses port 20 for all traffic|ICMP is a mail retrieval service',[[2,'p. 3'],[1,'T/F 5']]),
(8,'Spoofing and captive portals','Why are SSIDs, IP addresses, and captive portals insufficient proof of trust?','Spoofing impersonates an identifier such as an address or caller identity. An evil-twin wireless access point can imitate a familiar SSID and lure users; a Wi-Fi assessment device can demonstrate these risks but cannot automatically decrypt all nearby secure traffic. A captive portal presents network-access or acceptance steps; its appearance alone does not establish legitimacy. Verify the network and destination, and use authenticated secure protocols.','A familiar name is easy to copy. Trust requires verification beyond a displayed label.','A traveler sees two access points with the hotel’s name. The name alone cannot determine which is authorized.','Displayed names and addresses can be impersonated','Every matching SSID proves the same operator|A portal guarantees encrypted traffic|A Wi-Fi gadget automatically decrypts TLS',[[4,'09/08, 10/15']]),
(7,'Chapter 3 foundations and constraints','What additional Chapter 3 concepts should you recognize?', 'Steganography hides the existence of data; encryption hides readable content. ROT13 is a substitution cipher, and XOR gives 0 for equal input bits and 1 for different bits. Stream ciphers process streams; block ciphers process fixed-size blocks. Diffusion spreads a plaintext change through the output; confusion obscures the relation between key and ciphertext. Secure randomness and key management matter. Diffie-Hellman establishes a shared secret; ephemeral exchanges can support forward secrecy when used correctly. Downgrade attacks force weaker options. TPM and HSM protect cryptographic operations and keys; full-disk encryption protects stored data. Resource, power, and latency constraints influence implementation choices.','These are assigned-chapter recognition topics. Focus deeper discussion on the professor’s crypto, signature, hashing, and Bitcoin prompts.','A lost powered-off encrypted laptop needs storage protection. A compromised running session exposes data in use, so disk encryption alone is insufficient.','Match the mechanism and data state to the protection goal','Steganography always encrypts content|A TPM prevents every software exploit|Forward secrecy means keys never change',[[3,'Ch. 3, pp. 100–130']]),
]
for row in rows:add(*row)

