terms=[
('CIA','Confidentiality Integrity Availability',22),('IDS','Intrusion Detection System',12),('IPS','Intrusion Prevention System',26),('PCAP','Packet Capture',27),('DDoS','Distributed Denial of Service',28),('XSS','Cross Site Scripting',29),('SQLi','SQL Injection',29),('SET','Social Engineer Toolkit',31),('MFA','Multi Factor Authentication',31),('EDR','Endpoint Detection and Response',34),('SOC','Security Operations Center',34),('C2','Command and Control',13),('DLL','Dynamic Link Library',34),('NAC','Network Access Control',33),('GPO','Group Policy Object',33),('VM','Virtual Machine',35),('RSA','Rivest Shamir Adleman',39),('SHA','Secure Hash Algorithm',19),('TCP','Transmission Control Protocol',42),('UDP','User Datagram Protocol',42),('IP','Internet Protocol',42),('DNS','Domain Name System',43),('SNMP','Simple Network Management Protocol',43),('ICMP','Internet Control Message Protocol',43),('FTP','File Transfer Protocol',43),('SMTP','Simple Mail Transfer Protocol',43),('POP','Post Office Protocol',43),('SMB','Server Message Block',34),('HMAC','Hash based Message Authentication Code',37),('AES','Advanced Encryption Standard',38)]
acronym_details={
'CIA':('The three central goals of information security: restrict disclosure, prevent unauthorized changes, and keep authorized access available.','Confidentiality Identity Authorization|Control Integrity Authentication|Central Information Authority'),
'IDS':('A control that detects suspicious activity and raises alerts. Detection does not necessarily block the activity.','Intrusion Defense Service|Internet Detection Standard|Internal Data Security'),
'IPS':('A control that can actively prevent or disrupt suspicious activity, with tuning needed to avoid blocking legitimate work.','Intrusion Protection Server|Internet Policy Standard|Internal Packet Service'),
'PCAP':('Packet capture records packet bytes for investigation within sensor and storage limits. Encrypted content remains encrypted.','Protocol Control Access Policy|Packet Connection Authentication Protocol|Private Capture Authorization Process'),
'DDoS':('An availability attack using multiple sources to overwhelm or exhaust a target’s resources.','Direct Denial of Service|Distributed Detection of Spoofing|Dynamic Defense of Systems'),
'XSS':('Injection that causes attacker-controlled script to execute in a victim browser in a trusted site’s context.','Cross Server Scripting|Cross Site Spoofing|Extended Script Security'),
'SQLi':('Untrusted input changes the structure or meaning of a database query. Parameterized queries separate commands and data.','Structured Query Inspection|Server Query Integration|Secure Query Isolation'),
'SET':('TrustedSec’s toolkit for authorized social-engineering simulations, including fake-login credential-harvesting demonstrations.','Security Exploit Toolkit|Social Encryption Tool|System Enumeration Template'),
'MFA':('Authentication requiring factors from different categories, such as something known and something possessed. Phishing-resistant methods reduce common credential-phishing risks.','Multiple Firewall Authorization|Managed Factor Access|Multi File Authentication'),
'EDR':('Endpoint telemetry and response capabilities that help investigate and contain suspicious behavior on hosts.','Endpoint Data Recovery|External Detection and Routing|Encrypted Device Response'),
'SOC':('A security team or operational function that monitors threats, investigates alerts, and coordinates response.','System Operations Controller|Security Output Certificate|Service Origin Control'),
'C2':('Communication used to issue instructions to compromised systems and receive information from them.','Connection and Checksum|Control and Cryptography|Capture and Compare'),
'DLL':('A library of reusable code and data that Windows programs can load. A DLL is not merely a database of graphical objects.','Dynamic Login Layer|Distributed Link Loader|Digital Logic Library'),
'NAC':('Controls that assess and enforce device or user conditions for network access.','Network Authentication Cipher|Node Address Control|Network Activity Capture'),
'GPO':('A Windows domain policy object used to centrally distribute settings, including security configurations.','General Permission Override|Global Packet Option|Guest Protection Object'),
'VM':('A virtualized computer running a guest OS using resources provided through a hypervisor on a host.','Virtual Memory only|Verified Machine|Volume Manager'),
'RSA':('An asymmetric cryptographic family named for Rivest, Shamir, and Adleman. Classroom arithmetic uses products of primes and modular exponents.','Rivest Shannon Adleman|Random Security Algorithm|Remote Signature Authorization'),
'SHA':('A family of cryptographic hash algorithms. SHA-256 produces a 256-bit digest and is distinct from encryption.','Secure Host Authentication|Signed Hash Address|Shared Hash Algorithm'),
'TCP':('A transport protocol providing reliable ordered byte streams with sequencing, acknowledgments, and retransmission. It does not itself encrypt data.','Transportation Control Protocol|Transmission Connection Protocol|Transport Checksum Process'),
'UDP':('A transport protocol for datagrams that does not promise TCP-style delivery or ordering.','User Data Protection|Universal Datagram Protocol|Unified Delivery Process'),
'IP':('The network-layer protocol for addressing and best-effort routing of packets.','Internet Protection|Internal Protocol|Interconnection Process'),
'DNS':('A naming system that resolves domain records, including mappings of names to IP addresses.','Domain Network Security|Digital Naming Service|Distributed Node System'),
'SNMP':('An application protocol used to monitor and manage network devices.','Secure Network Mail Protocol|Simple Node Mapping Process|System Network Monitoring Port'),
'ICMP':('A network control and diagnostic protocol used for messages including echo requests and replies.','Internet Connection Management Protocol|Internal Control Mapping Process|Internet Cryptographic Message Protocol'),
'FTP':('A file-transfer protocol whose traditional form does not encrypt credentials or transferred data.','File Transport Protection|Fast Transfer Process|Firewall Tunneling Protocol'),
'SMTP':('An application protocol used to submit and relay email. The professor guide’s SMPT is a transposition error.','Secure Mail Transmission Protocol|Simple Message Transport Process|System Mail Transfer Port'),
'POP':('An application protocol used by clients to retrieve email from a mail server.','Packet Output Protocol|Private Office Protection|Post Origin Process'),
'SMB':('A protocol commonly used for sharing files and related resources across a network.','Secure Message Bridge|System Memory Block|Server Mail Broker'),
'HMAC':('A keyed hash construction for message integrity and authentication among parties sharing a secret. It does not encrypt the message.','Hash based Message Access Control|Host Message Authentication Cipher|Hashed Memory Authorization Code'),
'AES':('A symmetric block cipher used for efficient confidentiality protection when implemented with an appropriate secure mode and key management.','Asymmetric Encryption Standard|Advanced Encoding System|Authenticated Exchange Service')}
