for args in [(12,'Benign traffic triggers an IDS alert: _____.','False positive','False negative|True positive|True negative'),(14,'An incompatible consensus-rule change can produce a chain split: _____.','Hard fork','Soft checksum|Nonce|Digest'),(15,'A packet corruption comparison uses a _____.','Checksum','Signature key|Ciphertext|Proxy'),(1,'The encrypted form of plaintext is _____.','Ciphertext','Digest|Public key|Nonce'),(8,'Phishing delivered by voice is _____.','Vishing','Smishing|Hashing|Routing'),(9,'Sender routing information is investigated in the email _____.','Header','Body only|Attachment only|Font'),(19,'SHA-256 produces a digest containing _____ bits.','256','64|128|512'),(38,'To verify Alice’s signature, use Alice’s _____ key.','Public','Private|Shared secret|Recovery'),(38,'To decrypt material protected for Bob, use Bob’s _____ key.','Private','Public|Sender public|Nonce'),(40,'Miners vary a _____ while searching for valid proof of work.','Nonce','Password|Public key|Checksum'),(42,'The handshake order is SYN, _____, ACK.','SYN-ACK','FIN|DNS|UDP'),(32,'A keylogger can record input _____ transport encryption.','Before','Only after|Instead of all|Only during decryption')]:cloze(*args)

